:root {
  font-family: system-ui, sans-serif;
  color: #192e3a;
  background: #f4f7f9;
}
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 32px; }
h1 { font-size: 2.5rem; letter-spacing: -0.04em; margin: 0 0 32px; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.create-controls { display: flex; gap: 12px; }
#rename-form { margin-top: 24px; }
input { flex: 1; min-width: 0; border: 1px solid #82949e; border-radius: 6px; padding: 12px; font: inherit; }
button { border: 1px solid #1f576f; border-radius: 6px; background: #1f576f; color: white; padding: 12px 18px; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #163f51; }
button:disabled { opacity: 0.6; cursor: wait; }
button:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid #cd7900; outline-offset: 3px; }
select { border: 1px solid #82949e; border-radius: 6px; padding: 10px; font: inherit; background: white; }
.task-filter, .project-filter { margin-top: 24px; }
input[type="checkbox"] { flex: none; width: 22px; height: 22px; cursor: pointer; accent-color: #1f576f; }
[role="alert"] { color: #9c2424; }
ul { list-style: none; padding: 0; margin-top: 32px; }
li { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 20px; background: white; border: 1px solid #d5dfe5; border-radius: 8px; padding: 20px; margin-bottom: 12px; }
li span { overflow-wrap: anywhere; min-width: 0; }
li button { flex-shrink: 0; }
li form { width: 100%; }
#projects { margin-bottom: 24px; }
@media (max-width: 520px) {
  main { margin: 24px auto; padding: 20px; }
  .create-controls { flex-direction: column; }
  li { align-items: flex-start; flex-direction: column; }
}
